-- Neon PostgreSQL schema — faithful translation of src/db/schema.sql (SQLite).
-- Idempotent: safe to apply on every boot. Applied by src/db/postgres.js.
-- Dialect notes:
--   AUTOINCREMENT              -> GENERATED BY DEFAULT AS IDENTITY (allows explicit
--                                 ids during data migration; auto-generates otherwise)
--   DATETIME CURRENT_TIMESTAMP -> TIMESTAMPTZ DEFAULT now()
--   AFTER UPDATE triggers      -> single set_updated_at() function + per-table triggers
--   PRAGMA foreign_keys        -> not needed; PostgreSQL always enforces FKs

CREATE TABLE IF NOT EXISTS profile (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL,
    role TEXT NOT NULL,
    summary TEXT NOT NULL,
    contact_info TEXT,
    publication_state TEXT NOT NULL DEFAULT 'Draft' CHECK (publication_state IN ('Draft','Published','Archived')),
    singleton INTEGER NOT NULL DEFAULT 1 CHECK (singleton = 1),
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    UNIQUE (singleton)
);

CREATE TABLE IF NOT EXISTS project (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title TEXT NOT NULL,
    description TEXT,
    outcomes TEXT,
    roles TEXT,
    technologies TEXT,
    publication_state TEXT NOT NULL DEFAULT 'Draft' CHECK (publication_state IN ('Draft','Published','Archived')),
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS skill (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL,
    description TEXT,
    publication_state TEXT NOT NULL DEFAULT 'Draft' CHECK (publication_state IN ('Draft','Published','Archived')),
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS evidence (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    description TEXT,
    file_path TEXT,
    file_type TEXT,
    accessibility_status TEXT NOT NULL DEFAULT 'Public' CHECK (accessibility_status IN ('Public','Private/Restricted','Redacted','Unavailable')),
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS claim (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    statement TEXT NOT NULL,
    justification TEXT,
    source_entity_type TEXT CHECK (source_entity_type IN ('profile','project','skill')),
    source_entity_id BIGINT,
    publication_state TEXT NOT NULL DEFAULT 'Draft' CHECK (publication_state IN ('Draft','Published','Archived')),
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS experience (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    profile_id BIGINT NOT NULL,
    title TEXT NOT NULL,
    company TEXT NOT NULL,
    start_date TEXT NOT NULL,
    end_date TEXT,
    description TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY (profile_id) REFERENCES profile(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS education (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    profile_id BIGINT NOT NULL,
    institution TEXT NOT NULL,
    degree TEXT NOT NULL,
    field_of_study TEXT,
    start_date TEXT NOT NULL,
    end_date TEXT,
    description TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    FOREIGN KEY (profile_id) REFERENCES profile(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS project_skill (
    project_id BIGINT NOT NULL,
    skill_id BIGINT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT now(),
    PRIMARY KEY (project_id, skill_id),
    FOREIGN KEY (project_id) REFERENCES project(id) ON DELETE CASCADE,
    FOREIGN KEY (skill_id) REFERENCES skill(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS project_evidence (
    project_id BIGINT NOT NULL,
    evidence_id BIGINT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT now(),
    PRIMARY KEY (project_id, evidence_id),
    FOREIGN KEY (project_id) REFERENCES project(id) ON DELETE CASCADE,
    FOREIGN KEY (evidence_id) REFERENCES evidence(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS skill_evidence (
    skill_id BIGINT NOT NULL,
    evidence_id BIGINT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT now(),
    PRIMARY KEY (skill_id, evidence_id),
    FOREIGN KEY (skill_id) REFERENCES skill(id) ON DELETE CASCADE,
    FOREIGN KEY (evidence_id) REFERENCES evidence(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS claim_evidence (
    claim_id BIGINT NOT NULL,
    evidence_id BIGINT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT now(),
    PRIMARY KEY (claim_id, evidence_id),
    FOREIGN KEY (claim_id) REFERENCES claim(id) ON DELETE CASCADE,
    FOREIGN KEY (evidence_id) REFERENCES evidence(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS _migrations (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    filename TEXT NOT NULL UNIQUE,
    applied_at TIMESTAMPTZ DEFAULT now()
);

-- updated_at maintenance (replaces the per-table SQLite AFTER UPDATE triggers)
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS update_profile_timestamp ON profile;
CREATE TRIGGER update_profile_timestamp
BEFORE UPDATE ON profile
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS update_project_timestamp ON project;
CREATE TRIGGER update_project_timestamp
BEFORE UPDATE ON project
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS update_skill_timestamp ON skill;
CREATE TRIGGER update_skill_timestamp
BEFORE UPDATE ON skill
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS update_evidence_timestamp ON evidence;
CREATE TRIGGER update_evidence_timestamp
BEFORE UPDATE ON evidence
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS update_claim_timestamp ON claim;
CREATE TRIGGER update_claim_timestamp
BEFORE UPDATE ON claim
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS update_experience_timestamp ON experience;
CREATE TRIGGER update_experience_timestamp
BEFORE UPDATE ON experience
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS update_education_timestamp ON education;
CREATE TRIGGER update_education_timestamp
BEFORE UPDATE ON education
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE INDEX IF NOT EXISTS idx_project_publication_state ON project(publication_state);
CREATE INDEX IF NOT EXISTS idx_evidence_accessibility ON evidence(accessibility_status);
CREATE INDEX IF NOT EXISTS idx_skill_publication_state ON skill(publication_state);
CREATE INDEX IF NOT EXISTS idx_claim_publication_state ON claim(publication_state);
CREATE INDEX IF NOT EXISTS idx_claim_source ON claim(source_entity_type, source_entity_id);

-- ===== 002_cv_extension: CV population support (email/identity columns, category,
-- is_current/location/grade/deploy_url, person_skills, certifications, cv_references,
-- recommendations, population_warnings) =====
-- Transactional-safe: every statement is idempotent. Applied automatically as
-- part of scripts/cv-populate/populate.js and recorded here for fresh boots
-- (schema.postgres.sql mirrors these changes).

ALTER TABLE profile ADD COLUMN IF NOT EXISTS email TEXT;
ALTER TABLE profile ADD COLUMN IF NOT EXISTS location TEXT;
ALTER TABLE profile ADD COLUMN IF NOT EXISTS phone TEXT;
ALTER TABLE profile ADD COLUMN IF NOT EXISTS github TEXT;
ALTER TABLE profile ADD COLUMN IF NOT EXISTS portfolio TEXT;
ALTER TABLE profile ADD COLUMN IF NOT EXISTS linkedin TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS uq_profile_email ON profile (email);

ALTER TABLE skill ADD COLUMN IF NOT EXISTS category TEXT;

ALTER TABLE experience ADD COLUMN IF NOT EXISTS is_current BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE experience ADD COLUMN IF NOT EXISTS location TEXT;

ALTER TABLE project ADD COLUMN IF NOT EXISTS deploy_url TEXT;
ALTER TABLE project ADD COLUMN IF NOT EXISTS profile_id BIGINT REFERENCES profile(id) ON DELETE CASCADE;

ALTER TABLE education ADD COLUMN IF NOT EXISTS grade TEXT;

CREATE TABLE IF NOT EXISTS person_skills (
    person_id BIGINT NOT NULL REFERENCES profile(id) ON DELETE CASCADE,
    skill_id BIGINT NOT NULL REFERENCES skill(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ DEFAULT now(),
    PRIMARY KEY (person_id, skill_id)
);

CREATE TABLE IF NOT EXISTS certifications (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES profile(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    issuer TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS cv_references (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES profile(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    role TEXT,
    organization TEXT,
    email TEXT,
    phone TEXT,
    created_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS recommendations (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES profile(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    issuer TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

CREATE TABLE IF NOT EXISTS population_warnings (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    table_name TEXT NOT NULL,
    column_name TEXT,
    reason TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT now()
);

DROP TRIGGER IF EXISTS trg_certifications_updated_at ON certifications;
CREATE TRIGGER trg_certifications_updated_at
BEFORE UPDATE ON certifications
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

DROP TRIGGER IF EXISTS trg_recommendations_updated_at ON recommendations;
CREATE TRIGGER trg_recommendations_updated_at
BEFORE UPDATE ON recommendations
FOR EACH ROW EXECUTE FUNCTION set_updated_at();


-- ===== 003_dba_remediation: FK indexes, partial indexes, uniqueness, URL/pairing
-- CHECKs, audit_log + triggers, evidence soft delete, project ownership =====

CREATE INDEX IF NOT EXISTS idx_experience_profile_id        ON experience (profile_id);
CREATE INDEX IF NOT EXISTS idx_education_profile_id         ON education (profile_id);
CREATE INDEX IF NOT EXISTS idx_project_profile_id           ON project (profile_id);
CREATE INDEX IF NOT EXISTS idx_certifications_person_id     ON certifications (person_id);
CREATE INDEX IF NOT EXISTS idx_cv_references_person_id      ON cv_references (person_id);
CREATE INDEX IF NOT EXISTS idx_recommendations_person_id    ON recommendations (person_id);
CREATE INDEX IF NOT EXISTS idx_person_skills_skill_id       ON person_skills (skill_id);
CREATE INDEX IF NOT EXISTS idx_project_skill_skill_id       ON project_skill (skill_id);
CREATE INDEX IF NOT EXISTS idx_project_evidence_evidence_id ON project_evidence (evidence_id);
CREATE INDEX IF NOT EXISTS idx_skill_evidence_evidence_id   ON skill_evidence (evidence_id);
CREATE INDEX IF NOT EXISTS idx_claim_evidence_evidence_id   ON claim_evidence (evidence_id);

DROP INDEX IF EXISTS idx_project_publication_state;
CREATE INDEX IF NOT EXISTS idx_project_published_updated
  ON project (updated_at DESC) WHERE publication_state = 'Published';
DROP INDEX IF EXISTS idx_skill_publication_state;
CREATE INDEX IF NOT EXISTS idx_skill_published_name
  ON skill (name ASC) WHERE publication_state = 'Published';

CREATE UNIQUE INDEX IF NOT EXISTS uq_skill_name_ci ON skill (lower(name));
CREATE UNIQUE INDEX IF NOT EXISTS uq_project_person_title
  ON project (profile_id, lower(title)) WHERE profile_id IS NOT NULL;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'chk_evidence_file_path_url' AND conrelid = 'evidence'::regclass) THEN
    ALTER TABLE evidence ADD CONSTRAINT chk_evidence_file_path_url CHECK (file_path IS NULL OR file_path ~* '^https?://\S+$');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'chk_project_deploy_url' AND conrelid = 'project'::regclass) THEN
    ALTER TABLE project ADD CONSTRAINT chk_project_deploy_url CHECK (deploy_url IS NULL OR deploy_url ~* '^https?://\S+$');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'chk_claim_source_pair' AND conrelid = 'claim'::regclass) THEN
    ALTER TABLE claim ADD CONSTRAINT chk_claim_source_pair CHECK ((source_entity_type IS NULL) = (source_entity_id IS NULL));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'chk_evidence_has_content' AND conrelid = 'evidence'::regclass) THEN
    ALTER TABLE evidence ADD CONSTRAINT chk_evidence_has_content CHECK (description IS NOT NULL OR file_path IS NOT NULL);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'chk_experience_start_date_iso' AND conrelid = 'experience'::regclass) THEN
    ALTER TABLE experience ADD CONSTRAINT chk_experience_start_date_iso CHECK (start_date ~ '^\d{4}-\d{2}$');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'chk_education_start_date_iso' AND conrelid = 'education'::regclass) THEN
    ALTER TABLE education ADD CONSTRAINT chk_education_start_date_iso CHECK (start_date ~ '^\d{4}-\d{2}$');
  END IF;
END $$;

ALTER TABLE cv_references ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT now();
DROP TRIGGER IF EXISTS trg_cv_references_updated_at ON cv_references;
CREATE TRIGGER trg_cv_references_updated_at
BEFORE UPDATE ON cv_references
FOR EACH ROW EXECUTE FUNCTION set_updated_at();

ALTER TABLE evidence ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;
CREATE INDEX IF NOT EXISTS idx_evidence_deleted_at ON evidence (deleted_at) WHERE deleted_at IS NULL;

CREATE TABLE IF NOT EXISTS audit_log (
    id           BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    table_name   TEXT        NOT NULL,
    row_id       BIGINT,
    action       TEXT        NOT NULL CHECK (action IN ('INSERT','UPDATE','DELETE')),
    changed_by   TEXT,
    changed_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    old_data     JSONB,
    new_data     JSONB
);
CREATE INDEX IF NOT EXISTS idx_audit_log_table_row ON audit_log (table_name, row_id, changed_at DESC);

CREATE OR REPLACE FUNCTION fn_audit_row() RETURNS trigger AS $fn$
BEGIN
    INSERT INTO audit_log (table_name, row_id, action, changed_by, old_data, new_data)
    VALUES (
        TG_TABLE_NAME,
        CASE WHEN TG_OP = 'DELETE' THEN (to_jsonb(OLD)->>'id')::bigint ELSE (to_jsonb(NEW)->>'id')::bigint END,
        TG_OP,
        current_setting('app.user_id', true),
        CASE WHEN TG_OP IN ('UPDATE','DELETE') THEN to_jsonb(OLD) END,
        CASE WHEN TG_OP IN ('INSERT','UPDATE') THEN to_jsonb(NEW) END
    );
    RETURN COALESCE(NEW, OLD);
END;
$fn$ LANGUAGE plpgsql;

DO $$
DECLARE t TEXT;
BEGIN
    FOREACH t IN ARRAY ARRAY['profile','project','skill','evidence','claim','experience','education','certifications']
    LOOP
        EXECUTE format('DROP TRIGGER IF EXISTS audit_%1$s ON %1$s', t);
        EXECUTE format(
            'CREATE TRIGGER audit_%1$s AFTER INSERT OR UPDATE OR DELETE ON %1$s FOR EACH ROW EXECUTE FUNCTION fn_audit_row()', t);
    END LOOP;
END $$;

